const xmlComparisonMarker = "GITHUB_COM_DUMMY_WORKS_DUMMY_XML_COMPARISON_LITERAL"

func canonicalizeXmlForComparison(text string) (xmlComparison, error) {
	text = strings.TrimSpace(text)
	// Escape text before applying the legacy markup cleanup, so a literal
	// '>' in a value can not make the cleanup remove a preceding space.
	comparison, err := normalizeXmlTextEscaping(text)
	if err != nil {
		return xmlComparison{}, err
	}
	text = comparison.text
	// Protect literal content while the legacy regexes clean up markup.
	// Check after simulating carriage-return removal so cleanup cannot turn
	// existing XML text into a placeholder that gets replaced on restoration.
	markerPrefix := xmlComparisonMarker
	withoutCR := strings.ReplaceAll(text, "\r", "")
	for strings.Contains(withoutCR, markerPrefix) {
		markerPrefix += "X"
	}
	// Collect placeholder/original pairs for a single-pass restoration.
	var replacements []string
	protectLiteral := func(original string, asMarkup bool) string {
		marker := fmt.Sprintf("%s_%d_", markerPrefix, len(replacements)/2)
		if asMarkup {
			marker = "<?" + marker + "?>"
		}
		// XML 1.0 section 2.11 normalizes literal line endings before parsing.
		original = strings.ReplaceAll(strings.ReplaceAll(original, "\r\n", "\n"), "\r", "\n")
		replacements = append(replacements, marker, original)
		return marker
	}
	var protected bytes.Buffer
	// Track the buffered end of a start tag followed only by formatting whitespace.
	openingTagEnd := 0
	decoder := xml.NewDecoder(strings.NewReader(text))
	for {
		start := decoder.InputOffset()
		token, err := decoder.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return xmlComparison{}, err
		}
		original := text[start:decoder.InputOffset()]
		switch token.(type) {
		case xml.Comment, xml.ProcInst, xml.Directive:
			openingTagEnd = 0
			protected.WriteString(protectLiteral(original, true))
		case xml.StartElement:
			// Quoted attribute values can contain '>' and the other quote character.
			// Keep the original quotes and protect only the contents between them.
			cursor := 0
			for i := 0; i < len(original); i++ {
				quote := original[i]
				if quote != '\'' && quote != '"' {
					continue
				}
				end := i + 1
				for end < len(original) && original[end] != quote {
					end++
				}
				if end == len(original) {
					return xmlComparison{}, fmt.Errorf("unterminated XML attribute value")
				}
				protected.WriteString(original[cursor : i+1])
				protected.WriteString(protectLiteral(original[i+1:end], false))
				protected.WriteByte(quote)
				cursor = end + 1
				i = end
			}
			protected.WriteString(original[cursor:])
			openingTagEnd = protected.Len()
		case xml.CharData:
			// Check the source spelling so whitespace references and CDATA still count.
			if strings.Trim(original, " \t\r\n") != "" {
				openingTagEnd = 0
			}
			protected.WriteString(original)
		case xml.EndElement:
			// An already self-closing tag produces an end token without source bytes.
			if openingTagEnd > 0 && original != "" {
				protected.Truncate(openingTagEnd - 1)
				protected.WriteString("/>")
			} else {
				protected.WriteString(original)
			}
			openingTagEnd = 0
		default:
			openingTagEnd = 0
			protected.WriteString(original)
		}
	}
	text = protected.String()
	text = strings.ReplaceAll(text, "\r", "")
	text = removeWhitespaceBetweenTags(text)
	text = removeWhitespaceWithinTags(text)
	if len(replacements) > 0 {
		text = strings.NewReplacer(replacements...).Replace(text)
	}
	comparison.text = text
	return comparison, nil
}

func TestXmlComparisonPreservesText(t *testing.T) {
	withDefaultAttribute := func(value string) string {
		return `<!DOCTYPE v [<!ATTLIST v label CDATA "` + value + `">]><v/>`
	}
	for _, c := range []struct {
		name     string
		expected string
		actual   string
		equal    bool
	}{
		{"empty_prefixed", `<p:v xmlns:p="urn:test"></p:v>`, `<p:v xmlns:p="urn:test"/>`, true},
		{"empty_tag_space", `<v ></v>`, `<v/>`, true},
		{"empty_indented", "<v>\n\t</v>", `<v/>`, true},
		{"empty_siblings", `<root><v></v><v /><v ></v></root>`, `<root><v/><v/><v/></root>`, true},
		{
			"empty_prefixed_attribute",
			`<p:v xmlns:p="urn:test" label="a >b"></p:v>`,
			`<p:v xmlns:p="urn:test" label="a >b"/>`, true,
		},
		{
			"empty_prefixed_changed_attribute",
			`<p:v xmlns:p="urn:test" label="a >b"></p:v>`,
			`<p:v xmlns:p="urn:test" label="a>b"/>`, false,
		},
		{"empty_vs_text", `<v>x</v>`, `<v/>`, false},
		{"empty_vs_reference", `<v>&#32;</v>`, `<v/>`, false},
		{"empty_vs_cdata_space", `<v><![CDATA[ ]]></v>`, `<v/>`, false},
		{"empty_vs_comment", `<v><!--note--></v>`, `<v/>`, false},
		{"empty_vs_instruction", `<v><?p note?></v>`, `<v/>`, false},
		{"empty_vs_child", `<v><child/></v>`, `<v/>`, false},
		{"equivalent_escaping", `<v>x ></v>`, `<v>x &gt;</v>`, true},
		{"lost_space", `<v>x ></v>`, `<v>x&gt;</v>`, false},
		{"numeric_reference", `<v>x ></v>`, `<v>x &#62;</v>`, true},
		{"extra_space", `<v>x ></v>`, `<v>x  &gt;</v>`, false},
		{"tab_vs_newline", `<v>&#x9;</v>`, `<v>&#xA;</v>`, false},
		{"tab_vs_space", `<v>&#x9;</v>`, `<v>&#32;</v>`, false},
		{"lost_tab", `<v>&#x9;</v>`, `<v></v>`, false},
		{"space_vs_literal_tab", `<v>&#32;</v>`, "<v>\t</v>", false},
		{"attribute_space", `<v label="a >b"/>`, `<v label="a>b"/>`, false},
		{"attribute_single_quote", `<v label='a >b'/>`, `<v label='a>b'/>`, false},
		{"attribute_mixed_quotes", `<v label='a " >b'/>`, `<v label='a ">b'/>`, false},
		{"attribute_empty_element", `<v label="a >b"></v>`, `<v label="a >b"/>`, true},
		{"attribute_tag_spacing", `<v label="a >b" />`, `<v label="a >b"/>`, true},
		{"attribute_crlf", "<v label=\"a\r\nb\"/>", "<v label=\"a\nb\"/>", true},
		{"attribute_cr", "<v label=\"a\rb\"/>", "<v label=\"ab\"/>", false},
		{
			"attribute_many_literals",
			`<v a0="0" a1="1" a2="2" a3="3" a4="4" a5="5"` +
				` a6="6" a7="7" a8="8" a9="9" a10="10"/>`,
			`<v a0="0" a1="1" a2="2" a3="3" a4="4" a5="5"` +
				` a6="6" a7="7" a8="8" a9="9" a10="changed"/>`,
			false,
		},
		{
			"namespace_changed",
			`<p:v xmlns:p="urn:a" label="a >b"/>`,
			`<p:v xmlns:p="urn:b" label="a >b"/>`, false,
		},
		{"comment_markup", `<v><!--<c></c>--></v>`, `<v><!--<c/>--></v>`, false},
		{"comment_space", `<v><!--a >b--></v>`, `<v><!--a>b--></v>`, false},
		{"comment_crlf", "<v><!--a\r\nb--></v>", "<v><!--a\nb--></v>", true},
		{"comment_cr_as_lf", "<v><!--a\rb--></v>", "<v><!--a\nb--></v>", true},
		{"comment_cr", "<v><!--a\rb--></v>", `<v><!--ab--></v>`, false},
		{"doctype_cr_as_lf", withDefaultAttribute("a\rb"), withDefaultAttribute("a\nb"), true},
		{"doctype_crlf", withDefaultAttribute("a\r\nb"), withDefaultAttribute("a\nb"), true},
		{"doctype_cr", withDefaultAttribute("a\rb"), withDefaultAttribute("ab"), false},
		{"doctype_attribute_space", withDefaultAttribute("a >b"), withDefaultAttribute("a>b"), false},
		{"doctype_spacing", `<!DOCTYPE v  ><v/>`, `<!DOCTYPE v><v/>`, false},
		{"instruction_data", `<v><?p x > y?></v>`, `<v><?p x> y?></v>`, false},
		{"instruction_markup", `<v><?p <a></a>?></v>`, `<v><?p <a/>?></v>`, false},
		{"instruction_cr", "<v><?p x\ry?></v>", `<v><?p xy?></v>`, false},
		{"instruction_cr_as_lf", "<v><?p x\ry?></v>", "<v><?p x\ny?></v>", true},
		{"instruction_crlf_as_lf", "<v><?p x\r\ny?></v>", "<v><?p x\ny?></v>", true},
		{"instruction_indentation", "<v>\n<?p x > y?>\n</v>", `<v><?p x > y?></v>`, true},
		{
			"instruction_marker",
			"<v><!--<?" + xmlComparisonMarker + "_0_?>--><?p x?></v>",
			"<v><!--<?p x?>--><?p x?></v>",
			false,
		},
		{
			"attribute_marker",
			"<v a=\"" + xmlComparisonMarker + "_0_\" b=\"other\"/>",
			"<v a=\"other\" b=\"other\"/>",
			false,
		},
	} {
		t.Run(c.name, func(t *testing.T) {
			expected, err := canonicalizeXmlForComparison(c.expected)
			if err != nil {
				t.Fatal(err)
			}
			actual, err := canonicalizeXmlForComparison(c.actual)
			if err != nil {
				t.Fatal(err)
			}
			if (expected == actual) != c.equal {
				t.Fatalf("Unexpected comparison of %q and %q", expected, actual)
			}
		})
	}
}

// Assert that the serialization `other`, as XML document, equals the original
//
//	XML document `that` read from the `source`.
func assertSerializationEqualsDeserialization(
	t *testing.T,
	that string,
	other string,
	source string,
) (ok bool) {
	ok = true

	// NOTE (mristin):
	// The following hack is SUPER ugly and unsafe! However, it works. Given Go's
	// limited support for XML, we gave up on a safer approach :(. We tested
	// the following approaches before applying this hack:
	//  * A round-trip over `encoding/xml`. Failed due to
	//    https://github.com/golang/go/issues/13400.
	//  * Using `aqwari.net/xml/xmltree`. Failed as the special characters in the
	//    element content still has not been de-escaped or consistently escaped in
	//    a round trip.

	canonicalThat, err := canonicalizeXmlForComparison(that)
	if err != nil {
		t.Fatalf("Failed to normalize original XML from %s: %s", source, err)
		return false
	}
	canonicalOther, err := canonicalizeXmlForComparison(other)
	if err != nil {
		t.Fatalf("Failed to normalize serialized XML from %s: %s", source, err)
		return false
	}

	if canonicalThat.numericMarkup != canonicalOther.numericMarkup {
		t.Fatalf("Numeric XML markup differs in %s:\nORIGINAL:\n%sSERIALIZED:\n%s",
			source, canonicalThat.numericMarkup, canonicalOther.numericMarkup)
	}
	thatLines := strings.Split(canonicalThat.text, "\n")
	otherLines := strings.Split(canonicalOther.text, "\n")

	if canonicalThat.text != canonicalOther.text {
		b := new(strings.Builder)
		minLines := len(thatLines)
		if minLines > len(otherLines) {
			minLines = len(otherLines)
		}
		for i := 0; i < minLines; i++ {
			if thatLines[i] == otherLines[i] {
				b.WriteString(fmt.Sprintf("           %s\n", thatLines[i]))
			} else {
				b.WriteString(fmt.Sprintf("ORIGINAL   %s\n", thatLines[i]))
				b.WriteString(fmt.Sprintf("SERIALIZED %s\n", otherLines[i]))
				break
			}
		}

		ok = false
		t.Fatalf(
			"The canonicalized XML serialization of the de-serialized instance "+
				"from %s does not equal the canonicalized original XML document:\n"+
				"%s",
			source, b.String(),
		)
		return
	}

	return
}

// Assert that there is a de-serialization error.
//
// If [ourtesting.RecordMode] is set, the de-serialization error is re-recorded
// to `expectedPth`. Otherwise, the error is compared against the golden file
// `expectedPth`.
func assertIsDeserializationErrorAndEqualsExpectedOrRecord(
	t *testing.T,
	err error,
	source string,
	expectedPth string,
) (ok bool) {
	ok = true

	if err == nil {
		ok = false
		t.Fatalf("De-serialization error expected from %s, but got none", source)
		return
	}

	deseriaErr, is := err.(*ourxmlization.DeserializationError)
	if !is {
		ok = false
		t.Fatalf(
			"Expected a de-serialization error, "+
				"but got an error of type %T from %s: %v",
			err, source, err,
		)
		return
	}

	// Add a new line for POSIX systems.
	got := deseriaErr.Error() + "\n"

	if ourtesting.RecordMode {
		parent := filepath.Dir(expectedPth)
		err := os.MkdirAll(parent, os.ModePerm)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to create the directory %s: %s", parent, err.Error(),
				),
			)
		}

		err = os.WriteFile(expectedPth, []byte(got), 0644)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to write to the file %s: %s", expectedPth, err.Error(),
				),
			)
		}
	} else {
		_, err := os.Stat(expectedPth)
		if err != nil {
			ok = false
			t.Fatalf(
				"Failed to stat the file %s: %s; if the file does not exist, "+
					"you probably want to record the test data by "+
					"setting the environment variable %s",
				expectedPth, err.Error(), ourtesting.RecordModeEnvironmentVariableName,
			)
			return
		}

		bb, err := os.ReadFile(expectedPth)
		if err != nil {
			panic(
				fmt.Sprintf(
					"Failed to read from file %s: %s", expectedPth, err.Error(),
				),
			)
		}

		expected := string(bb)

		// NOTE (mristin):
		// Git automatically strips and adds `\r`, so we have to remove it here
		// to obtain a canonical text.
		expected = strings.Replace(expected, "\r", "", -1)

		if expected != got {
			ok = false
			t.Fatalf(
				"What we got differs from the expected in %s. "+
					"We got:\n%s\nWe expected:\n%s",
				expectedPth, got, expected,
			)
			return
		}
	}

	return
}

func TestXmlNumericComparison(t *testing.T) {
	// These fragments exercise comparison at typed paths, without model verification.
	for _, path := range []struct {
		kind, prefix, suffix string
	}{
		{"json:array", "<something xmlns=\"https://dummy.com\"><values><data xmlns=\"\"><value><double>", "</double></value></data></values></something>"},
		{"json:double", "<something xmlns=\"https://dummy.com\"><value><double xmlns=\"\">", "</double></value></something>"},
		{"json:object", "<something xmlns=\"https://dummy.com\"><mapping><member xmlns=\"\"><name>x</name><value><double>", "</double></value></member></mapping></something>"},
	} {
		t.Run(path.kind, func(t *testing.T) {
			for _, c := range []struct {
				name, left, right string
				equal             bool
			}{
				{"decimal", "42.0", "42", true},
				{"exponent", "21668651.6", "2.16686516e+07", true},
				{"leading_zeroes", "+0042.00", "42", true},
				{"exponent_case", "4.2E1", "4.2e+01", true},
				{"negative", "-42.00", "-4.2e1", true},
				{"small", "0.0000000001", "1e-10", true},
				{"smallest_subnormal", "5e-324", "4.9406564584124654e-324", true},
				{"subnormal_vs_zero", "5e-324", "0", false},
				{"largest_finite", "1.7976931348623157e308", "1.7976931348623157E+308", true},
				{"different", "42", "43", false},
				{"adjacent_doubles", "1", "1.0000000000000002", false},
				{"integer_precision", "9007199254740991", "9007199254740992", false},
				{"signed_zero", "0", "-0", false},
				{"negative_zero", "-0.0", "-0e0", true},
				{"same_instruction", "<?p x > y?>42.0", "<?p x > y?>42", true},
				{"different_instruction", "<?p x > y?>42.0", "<?p x> y?>42", false},
				{"moved_instruction", "4<?p x?>2", "42<?p x?>", false},
				{"moved_comment", "4<!--c-->2", "42<!--c-->", false},
				{"split_comment", "4<!--c-->2.0", "4<!--c-->2", true},
				{"split_instruction", "4<?p x?>2.0", "4<?p x?>2", true},
				{"changed_number", "4<!--c-->2", "4<!--c-->3", false},
				{"changed_comment", "4<!--c-->2", "4<!--d-->2", false},
				{"changed_offset", "12<!--c-->3.0", "1<!--c-->23", false},
				{"missing_comment", "4<!--c-->2", "42", false},
				{"leading_or_trailing", "<?p x?>42", "42<?p x?>", false},
				{"trailing_markup", "42.0<!--c-->", "42<!--c-->", true},
			} {
				t.Run(c.name, func(t *testing.T) {
					left, err := canonicalizeXmlForComparison(path.prefix + c.left + path.suffix)
					if err != nil {
						t.Fatal(err)
					}
					right, err := canonicalizeXmlForComparison(path.prefix + c.right + path.suffix)
					if err != nil {
						t.Fatal(err)
					}
					want := c.equal && path.kind != "text"
					if (left == right) != want {
						t.Fatalf("Unexpected comparison of %q and %q", left, right)
					}
				})
			}
			if path.kind == "text" {
				return
			}
			for _, c := range []struct{ input, want string }{
				{"4<![CDATA[2]]>", "42"},
				{"4&#50;", "42"},
				{" 42 ", "42"},
				{" <![CDATA[4]]><?p x?><!--c-->&#50; ", "4<?p x?><!--c-->2"},
				{" <!--a-->42.0<?p x?> ", "<!--a-->42<?p x?>"},
			} {
				input := path.prefix + c.input + path.suffix
				instanceNumber, err := canonicalizeXmlForComparison(input)
				if err != nil {
					t.Fatal(err)
				}
				expected, err := canonicalizeXmlForComparison(path.prefix + c.want + path.suffix)
				if err != nil {
					t.Fatal(err)
				}
				if instanceNumber != expected {
					t.Fatalf("Expected %q, got %q", expected, instanceNumber)
				}
			}
			for _, spelling := range []string{
				"", " ", "nan", "Infinity", "0x1p0", "1_0", "1 2",
				"<v>42</v>", "4<?p x?> 2", "42" + string(rune(160)),
			} {
				if _, err := canonicalizeXmlForComparison(path.prefix + spelling + path.suffix); err == nil {
					t.Fatalf("Accepted invalid numeric content %q", spelling)
				}
			}
			for _, c := range []struct {
				spelling, want string
			}{
				{"INF", "INF"}, {"-INF", "-INF"}, {"NaN", "NaN"}, {"1e9999", "INF"},
			} {
				canonical, err := canonicalizeXmlForComparison(path.prefix + c.spelling + path.suffix)
				if strings.HasPrefix(path.kind, "json:") {
					if err == nil {
						t.Fatalf("Accepted non-finite JSON number %q", c.spelling)
					}
				} else {
					if err != nil {
						t.Fatal(err)
					}
					if canonical.text != path.prefix+c.want+path.suffix {
						t.Fatalf("Unexpected non-finite model number: %q", canonical)
					}
				}
			}
		})
	}
}

